// Generate types from the OpenAPI specs of the server to type check
// them against the corresponding service interfaces.
//
//   npm run test:openapi
//
// The generated files (tests/openapi/.schemas) are not committed.
// Prerequisite: server/docs/source/openapi/_include (not committed).
import { existsSync, mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { basename } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'

const includeDir = fileURLToPath(
  new URL('../../server/docs/source/openapi/_include/', import.meta.url)
)
const outDir = fileURLToPath(new URL('../tests/openapi/.schemas/', import.meta.url))

const specs = existsSync(includeDir)
  ? readdirSync(includeDir)
      .filter((f) => f.endsWith('.yaml'))
      .sort()
  : []
if (specs.length === 0) {
  console.error(`No OpenAPI specs: '${includeDir}'`)
  process.exit(1)
}

rmSync(outDir, { recursive: true, force: true })
mkdirSync(outDir, { recursive: true })

const banner = '/* eslint-disable */\n// Auto-generated by scripts/openapi-schema.js\n'

for (const file of specs) {
  const ast = await openapiTS(pathToFileURL(includeDir + file))
  const target = `${outDir}${basename(file, '.yaml')}.d.ts`
  writeFileSync(target, banner + astToString(ast))
}
